contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function test(uint256 amount) public {
        require(address(this).balance >= amount);
        // fund the contract through its payable fallback
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);
        require(address(c).balance == amount);

        // a call from a non-owner must revert and leave the balance untouched
        bool ok = true;
        // State-changing call must be top-level: perform it via a separate guarded transaction is impossible here,
        // so we use a low-level call (top-level statement) and capture the revert boolean.
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("withdrawAll(address)", address(this))
        );
        ok = success;

        uint256 balAfter = address(c).balance;
        // In P: the call reverted, so no funds moved and ok is false.
        // In M: the transfer executes before the ownership check, so the transfer
        // is observable as successful before the (then-failing) check.
        assert(ok == false || balAfter != amount);
    }
}

