contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Fund c through its payable fallback (top-level call).
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded);

        // The caller of withdrawAll is address(this); it must be the owner
        // for the withdrawal path to be reachable.
        require(c.owner() == address(this));

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }

        assert(
            reverted ||
            (address(c).balance == 0 &&
             address(this).balance == beforeThis + beforeC)
        );
    }

    receive() external payable {}
}

